package com.gameaggregator.auditservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="audit_logs",indexes={@Index(name="idx_audit_tenant_time",columnList="tenantId,occurredAt"),@Index(name="idx_audit_resource",columnList="resourceType,resourceId")}) public class AuditLog{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String eventId;public UUID tenantId;@Column(nullable=false)public UUID actorId;@Enumerated(EnumType.STRING)@Column(nullable=false)public AuditAction action;@Column(nullable=false)public String resourceType;@Column(nullable=false)public String resourceId;public String requestId;public String correlationId;public String ipAddress;@Lob public String beforeJson;@Lob public String afterJson;@Column(nullable=false)public Instant occurredAt;@Column(nullable=false)public Instant ingestedAt=Instant.now();protected AuditLog(){}public AuditLog(String e,UUID t,UUID a,AuditAction x,String rt,String ri,String q,String c,String ip,String b,String n,Instant o){eventId=e;tenantId=t;actorId=a;action=x;resourceType=rt;resourceId=ri;requestId=q;correlationId=c;ipAddress=ip;beforeJson=b;afterJson=n;occurredAt=o;}}